import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { testApp, type TestApp } from '../app.fixtures.ts';
import { installRoot } from './package-manager.ts';

let app: TestApp;

beforeEach(() => {
  app = testApp();
});

afterEach(() => {
  app.remove();
});

const YARN_1_LOCKFILE =
  '# THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.\n# yarn lockfile v1\n\n\n';
const YARN_4_LOCKFILE =
  '# This file is generated by running "yarn install" inside your project.\n# Manual changes might be lost - proceed with caution!\n\n__metadata:\n  version: 10\n  cacheKey: 10c0\n';

describe('installRoot', () => {
  it.each([
    ['bun.lock', '', 'bun'],
    ['bun.lockb', '', 'bun'],
    ['pnpm-lock.yaml', '', 'pnpm'],
    ['yarn.lock', YARN_4_LOCKFILE, 'yarn'],
    ['yarn.lock', '', 'yarn'],
    ['yarn.lock', YARN_1_LOCKFILE, 'yarn-classic'],
    ['package-lock.json', '', 'npm'],
  ])('reads %s holding %j as %s', (lockfile, content, manager) => {
    app.write(lockfile, content);

    expect(installRoot(app.root)).toEqual({ manager, dir: app.root, lockfile });
  });

  it("finds a workspace's lockfile above the app", () => {
    app.write('pnpm-lock.yaml', '');
    app.write('clients/tv/package.json', {});

    expect(installRoot(join(app.root, 'clients/tv'))).toEqual({
      manager: 'pnpm',
      dir: app.root,
      lockfile: 'pnpm-lock.yaml',
    });
  });

  it('finds none where no directory up to the root holds a lockfile', () => {
    expect(installRoot(app.root)).toBeNull();
  });
});
